package com.qcsitemanager.app;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import android.content.ContentValues;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.BufferedWriter;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;

public class MainActivity extends Activity {
    Db db; LinearLayout root, body, nav; String page="Dashboard"; String pendingPhoto=""; static final int PICK_PHOTO=44, SAVE_REPORT=45;
    int green=Color.rgb(23,107,85), dark=Color.rgb(18,60,50), pale=Color.rgb(239,246,243), ink=Color.rgb(30,43,39);
    @Override public void onCreate(Bundle b){super.onCreate(b); db=new Db(this); show();}
    TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(ink);t.setPadding(0,5,0,5);if(bold)t.setTypeface(null,1);return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(16,12,16,16);return l;}
    Button button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
    void show(){
        root=column(); root.setPadding(0,0,0,0); root.setBackgroundColor(Color.WHITE);
        TextView header=text("QC SITE MANAGER\nCLIENT QUALITY CONTROL",20,true);header.setTextColor(Color.WHITE);header.setBackgroundColor(dark);header.setPadding(18,18,18,18);root.addView(header);
        HorizontalScrollView hsv=new HorizontalScrollView(this); nav=new LinearLayout(this);nav.setOrientation(0);
        String[] pages={"Dashboard","Inspections","SOR","Cube Tests","Documents","Reports"};for(String p:pages){Button b=button(p,()->{page=p;show();});b.setTextColor(p.equals(page)?green:ink);nav.addView(b);}hsv.addView(nav);root.addView(hsv);
        ScrollView scroll=new ScrollView(this);body=column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
        switch(page){case "Dashboard":dashboard();break;case "Inspections":inspections();break;case "SOR":sors();break;case "Cube Tests":cubes();break;case "Documents":documents();break;case "Reports":reports();break;}
    }
    int count(String table,String where){Cursor c=db.count(table,where);c.moveToFirst();int n=c.getInt(0);c.close();return n;}
    void dashboard(){body.addView(text("Project quality overview",22,true));body.addView(text("Offline-first storage on this phone. Back up/export records regularly.",14,false));
        body.addView(text("Open SORs: "+count("sor","status!='Closed'"),18,true));body.addView(text("Inspections logged: "+count("inspections",null),18,true));body.addView(text("Cube records: "+count("cubes",null),18,true));body.addView(text("Documents registered: "+count("documents",null),18,true));
        body.addView(button("+ Raise a new SOR",()->{page="SOR";show();sorForm();}));body.addView(button("+ Add cube test record",()->{page="Cube Tests";show();cubeForm();}));body.addView(button("+ Record inspection",()->{page="Inspections";show();inspectionForm();}));body.addView(text("Important: SOR closure should only occur after Client QC verifies the actual rectification at site.",14,true));}
    EditText field(LinearLayout parent,String hint){EditText e=new EditText(this);e.setHint(hint);parent.addView(e);return e;}
    void pickPhoto(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_PHOTO);}
    @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==PICK_PHOTO&&c==RESULT_OK&&d!=null&&d.getData()!=null){pendingPhoto=d.getData().toString();new AlertDialog.Builder(this).setMessage("Photo selected. Save the form to attach its reference.").setPositiveButton("OK",null).show();}if(r==SAVE_REPORT&&c==RESULT_OK&&d!=null&&d.getData()!=null)writeCsv(d.getData());}
    void sorForm(){LinearLayout f=column(); EditText loc=field(f,"Villa / road / floor / exact location");EditText cat=field(f,"Work category (RCC, blockwork, roadwork...)");EditText title=field(f,"Observation title");EditText detail=field(f,"Defect and required corrective action");EditText due=field(f,"Target date (YYYY-MM-DD)");f.addView(button("Attach photo",this::pickPhoto));f.addView(button("Save SOR",()->{if(loc.length()==0||title.length()==0){msg("Location and observation title are required.");return;}ContentValues v=new ContentValues();v.put("code","SOR-"+new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date()));v.put("location",loc.getText().toString());v.put("category",cat.getText().toString());v.put("title",title.getText().toString());v.put("details",detail.getText().toString());v.put("due",due.getText().toString());v.put("created",today());v.put("status","Open");v.put("photo",pendingPhoto);db.add("sor",v);pendingPhoto="";msg("SOR saved on this phone.");show();}));body.addView(f);}
    void sors(){body.addView(text("Site Observation Reports",22,true));body.addView(button("+ Create SOR",this::sorForm));Cursor c=db.all("sor");if(c.getCount()==0)body.addView(text("No SORs yet. Create your first site observation.",15,false));while(c.moveToNext()){String id=c.getString(c.getColumnIndexOrThrow("id")),code=c.getString(c.getColumnIndexOrThrow("code")),loc=c.getString(c.getColumnIndexOrThrow("location")),title=c.getString(c.getColumnIndexOrThrow("title")),status=c.getString(c.getColumnIndexOrThrow("status"));body.addView(text(code+" · "+status,16,true));body.addView(text(loc+"\n"+title,15,false));body.addView(button("Update status / QC remark",()->sorUpdate(id,code,status)));}c.close();}
    void sorUpdate(String id,String code,String old){String[] states={"Open","In Progress","Under Verification","Closed","Reopened"};EditText remark=new EditText(this);remark.setHint("Client QC verification / rejection remark");new AlertDialog.Builder(this).setTitle(code+" status").setSingleChoiceItems(states,-1,(dialog,which)->{ContentValues v=new ContentValues();v.put("status",states[which]);v.put("qc_remark",remark.getText().toString());db.update("sor",v,id);dialog.dismiss();show();}).setView(remark).setNegativeButton("Cancel",null).show();}
    void cubeForm(){LinearLayout f=column();EditText el=field(f,"Element / villa / road");EditText grade=field(f,"Concrete grade (M20/M25/M30)");EditText cast=field(f,"Casting date YYYY-MM-DD");EditText d7=field(f,"7-day test date");EditText s7=field(f,"7-day average strength MPa");EditText d28=field(f,"28-day test date");EditText s28=field(f,"28-day average strength MPa");EditText lab=field(f,"Lab / report reference");EditText rem=field(f,"Client QC remark");f.addView(button("Attach lab report / image",this::pickPhoto));f.addView(button("Save cube record",()->{if(el.length()==0||grade.length()==0||cast.length()==0){msg("Element, grade and casting date are required.");return;}ContentValues v=new ContentValues();v.put("element",el.getText().toString());v.put("grade",grade.getText().toString());v.put("cast_date",cast.getText().toString());v.put("test7_date",d7.getText().toString());v.put("strength7",s7.getText().toString());v.put("test28_date",d28.getText().toString());v.put("strength28",s28.getText().toString());v.put("lab",lab.getText().toString()+(pendingPhoto.isEmpty()?"":" | Attachment: "+pendingPhoto));v.put("remark",rem.getText().toString());v.put("status",s28.length()>0?"28-day result entered":s7.length()>0?"7-day result entered":"Tests pending");db.add("cubes",v);pendingPhoto="";msg("Cube record saved on this phone.");show();}));body.addView(f);}
    void cubes(){body.addView(text("Concrete cube test register",22,true));body.addView(button("+ Add cube record",this::cubeForm));Cursor c=db.all("cubes");if(c.getCount()==0)body.addView(text("No cube records yet.",15,false));while(c.moveToNext()){body.addView(text(c.getString(c.getColumnIndexOrThrow("element"))+" · "+c.getString(c.getColumnIndexOrThrow("grade")),17,true));body.addView(text("Cast: "+c.getString(c.getColumnIndexOrThrow("cast_date"))+" | 7-day: "+c.getString(c.getColumnIndexOrThrow("strength7"))+" MPa | 28-day: "+c.getString(c.getColumnIndexOrThrow("strength28"))+" MPa\nStatus: "+c.getString(c.getColumnIndexOrThrow("status")),14,false));}c.close();body.addView(text("Strength results are recorded for QC review; acceptance must follow the approved mix, project specifications and applicable standards.",13,false));}
    void inspectionForm(){LinearLayout f=column();EditText loc=field(f,"Villa / road / floor / location");EditText cat=field(f,"Inspection category");EditText chk=field(f,"Checklist / inspection points");EditText status=field(f,"Status: Pending / Accepted / Rejected");EditText rem=field(f,"Client QC remarks / corrective action");f.addView(button("Attach photo",this::pickPhoto));f.addView(button("Save inspection",()->{if(loc.length()==0){msg("Location is required.");return;}ContentValues v=new ContentValues();v.put("location",loc.getText().toString());v.put("category",cat.getText().toString());v.put("checklist",chk.getText().toString());v.put("status",status.length()==0?"Pending":status.getText().toString());v.put("remark",rem.getText().toString());v.put("date",today());v.put("photo",pendingPhoto);db.add("inspections",v);pendingPhoto="";msg("Inspection saved.");show();}));body.addView(f);}
    void inspections(){body.addView(text("Inspections & checklists",22,true));body.addView(button("+ Record inspection",this::inspectionForm));Cursor c=db.all("inspections");if(c.getCount()==0)body.addView(text("No inspection records yet.",15,false));while(c.moveToNext()){body.addView(text(c.getString(c.getColumnIndexOrThrow("location"))+" · "+c.getString(c.getColumnIndexOrThrow("category")),17,true));body.addView(text(c.getString(c.getColumnIndexOrThrow("status"))+" | "+c.getString(c.getColumnIndexOrThrow("remark")),14,false));}c.close();}
    void documents(){body.addView(text("Quality document register",22,true));LinearLayout f=column();EditText title=field(f,"Document title");EditText cat=field(f,"Category: ITP / MS / MIR / calibration / NCR");EditText ref=field(f,"Document number / file reference");EditText note=field(f,"Revision / expiry / remarks");f.addView(button("Attach document or photo",this::pickPhoto));f.addView(button("Save document record",()->{if(title.length()==0){msg("Document title is required.");return;}ContentValues v=new ContentValues();v.put("title",title.getText().toString());v.put("category",cat.getText().toString());v.put("reference",ref.getText().toString()+(pendingPhoto.isEmpty()?"":" | File: "+pendingPhoto));v.put("note",note.getText().toString());v.put("date",today());db.add("documents",v);pendingPhoto="";msg("Document register entry saved.");show();}));body.addView(f);Cursor c=db.all("documents");while(c.moveToNext())body.addView(text(c.getString(c.getColumnIndexOrThrow("title"))+"\n"+c.getString(c.getColumnIndexOrThrow("category"))+" · "+c.getString(c.getColumnIndexOrThrow("reference")),15,false));c.close();}
    void reports(){body.addView(text("QC reports & export",22,true));body.addView(text("Export SOR, inspection, cube and document registers as CSV files. Open them in Excel. This export contains records only; attached photos remain on their original device URIs.",14,false));body.addView(button("Export SOR register (CSV)",()->createReport("sor")));body.addView(button("Export cube register (CSV)",()->createReport("cubes")));body.addView(button("Export inspection register (CSV)",()->createReport("inspections")));body.addView(button("Export document register (CSV)",()->createReport("documents")));body.addView(text("PDF daily/weekly summaries and cloud-synced reports are planned for the next phase.",13,false));}
    String reportTable="";void createReport(String table){reportTable=table;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("text/csv");i.putExtra(Intent.EXTRA_TITLE,table+"_QC_"+today()+".csv");startActivityForResult(i,SAVE_REPORT);}
    void writeCsv(Uri uri){try(OutputStream os=getContentResolver().openOutputStream(uri);BufferedWriter w=new BufferedWriter(new OutputStreamWriter(os))){Cursor c=db.all(reportTable);for(int j=0;j<c.getColumnCount();j++){if(j>0)w.write(",");w.write(csv(c.getColumnName(j)));}w.write("\n");while(c.moveToNext()){for(int j=0;j<c.getColumnCount();j++){if(j>0)w.write(",");w.write(csv(c.getString(j)));}w.write("\n");}c.close();msg("CSV report exported successfully.");}catch(Exception e){msg("Export failed: "+e.getMessage());}}
    String csv(String s){if(s==null)return "";return "\""+s.replace("\"","\"\"").replace("\n"," ")+"\"";}
    String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
    void msg(String s){new AlertDialog.Builder(this).setTitle("QC Site Manager").setMessage(s).setPositiveButton("OK",null).show();}
}
